<script>
(function(){
 const form=document.getElementById('registerForm');if(!form)return;
 document.querySelectorAll('.oys-user-page .toggle-password').forEach(function(btn){btn.addEventListener('click',function(){const el=document.getElementById(btn.dataset.target);if(!el)return;const showing=el.type==='password';el.type=showing?'text':'password';btn.textContent=showing?'Hide':'Show';btn.setAttribute('aria-label',showing?'Hide password':'Show password');});});
 const image=document.getElementById('image'),preview=document.getElementById('profilePreview');let previousUrl=null;
 image.addEventListener('change',function(){if(previousUrl){URL.revokeObjectURL(previousUrl);previousUrl=null;}const f=image.files&&image.files[0];if(f&&f.type.startsWith('image/')){previousUrl=URL.createObjectURL(f);preview.src=previousUrl;preview.style.display='block';}else{preview.removeAttribute('src');preview.style.display='none';}});
 form.addEventListener('submit',function(event){const pass=document.getElementById('password').value,confirmation=document.getElementById('password_confirmation').value,passError=document.getElementById('passwordError'),confirmError=document.getElementById('confirmationError');passError.style.display='none';confirmError.style.display='none';if((pass.length>0&&pass.length<8)||(false&&pass.length<8)){event.preventDefault();passError.textContent='Password must be at least 8 characters long.';passError.style.display='block';document.getElementById('password').focus();return;}if(pass!==confirmation){event.preventDefault();confirmError.textContent='Password confirmation does not match.';confirmError.style.display='block';document.getElementById('password_confirmation').focus();}});
})();
</script>
